package ro.leo.visual;
import android.content.*;import android.os.*;import java.io.*;import java.util.*;import org.json.*;

/** Explicit preview/confirmation before replacing the supported Leo data. */
public final class BackupActivity extends LeoActivity {
 private File boundary;private boolean busy;
 protected void onCreate(Bundle b){super.onCreate(b);worker.execute(new Runnable(){public void run(){try{BackupEngine.recover(BackupActivity.this);ui(new Runnable(){public void run(){String path=getIntent().getStringExtra("file");if(path==null)home();else preview(new File(path));}});}catch(Exception e){ui(new Runnable(){public void run(){begin("Recuperare backup");root.addView(text("Copia de recuperare este păstrată local. Reinstalează tastatura Leo și redeschide Backup dacă furnizorul dicționarului lipsește.",17));footer("","","Înapoi");}});}}});}
 private void home(){busy=false;list("Backup Leo",Arrays.asList("Creează backup","Restaurează din fișier","Copii automate de recuperare","Ce include backup-ul","Contacte și SMS · selectiv"),0,new Choice(){public void pick(int i){if(i==4)startActivity(new Intent(BackupActivity.this,PeopleBackupActivity.class));else if(i==0)destinations();else if(i==1)roots();else if(i==2){boundary=new File(getFilesDir(),"documents/Backup-rollback");boundary.mkdirs();browse(boundary);}else options("Date locale incluse",new String[]{"Teme, fundal și ordinea aplicațiilor","Scurtături și favorite","Notițe și ciorna notiței","Dicționar T9 și opțiuni tastatură","Fără conturi, agendă sau SMS","Fișier personal, fără criptare"},new Choice(){public void pick(int n){}});}},"",null);}
 private void destinations(){final ArrayList<File> folders=new ArrayList<File>();ArrayList<String> names=new ArrayList<String>();for(Map.Entry<String,File> r:LeoFileProvider.roots(this).entrySet()){folders.add(new File(r.getValue(),r.getKey().equals("leo")?"Backup":"Documents/LeoBackups"));names.add(r.getKey().equals("phone")?"Memorie telefon":r.getKey().equals("leo")?"Documente Leo":"Card SD");}list("Salvează backup",names,0,new Choice(){public void pick(final int i){if(busy)return;busy=true;begin("Creez backup");root.addView(text("Se salvează local…",18));footer("","","Așteaptă");worker.execute(new Runnable(){public void run(){try{final File result=BackupEngine.export(BackupActivity.this,folders.get(i));ui(new Runnable(){public void run(){busy=false;begin("Backup salvat");root.addView(text(result.getName()+"\n\n"+android.text.format.Formatter.formatFileSize(BackupActivity.this,result.length())+"\n\nÎl găsești în Fișiere Leo; conține date personale.",17),new android.widget.LinearLayout.LayoutParams(-1,0,1));back=new Runnable(){public void run(){home();}};footer("","","Înapoi");}});}catch(final Exception e){ui(new Runnable(){public void run(){home();notice("Backup eșuat: "+e.getMessage());}});}}});}},"",null);back=new Runnable(){public void run(){home();}};}
 private void roots(){final LinkedHashMap<String,File> roots=LeoFileProvider.roots(this);final ArrayList<File> dirs=new ArrayList<File>(roots.values());ArrayList<String> names=new ArrayList<String>();for(String key:roots.keySet())names.add(key.equals("phone")?"Memorie telefon":key.equals("leo")?"Documente Leo":"Card SD");list("Caută backup",names,0,new Choice(){public void pick(int i){boundary=dirs.get(i);browse(boundary);}},"",null);back=new Runnable(){public void run(){home();}};}
 private void browse(final File dir){try{if(!LeoFileProvider.inside(boundary,dir))throw new IOException();File[] all=dir.listFiles();if(all==null)throw new IOException();Arrays.sort(all,new Comparator<File>(){public int compare(File a,File b){return a.isDirectory()!=b.isDirectory()?a.isDirectory()?-1:1:a.getName().compareToIgnoreCase(b.getName());}});final ArrayList<File> files=new ArrayList<File>();ArrayList<String> labels=new ArrayList<String>();for(File f:all)if(files.size()<300&&LeoFileProvider.inside(boundary,f)&&(f.isDirectory()||f.getName().endsWith(".leo-backup.json"))){files.add(f);labels.add((f.isDirectory()?"▸ ":"")+f.getName());}list("Backup-uri locale",labels,0,new Choice(){public void pick(int i){File f=files.get(i);if(f.isDirectory())browse(f);else preview(f);}},"",null);back=new Runnable(){public void run(){if(dir.equals(boundary))roots();else browse(dir.getParentFile());}};}catch(IOException e){notice("Folder inaccesibil");}}
 private void preview(final File file){if(busy)return;boolean allowed=false;try{for(File root:LeoFileProvider.roots(this).values())if(LeoFileProvider.inside(root,file))allowed=true;}catch(IOException ignored){}if(!allowed||!file.isFile()){home();notice("Backup în afara stocării permise");return;}busy=true;begin("Verific backup-ul");root.addView(text("Verific integritatea și formatul…",18));footer("","","Așteaptă");worker.execute(new Runnable(){public void run(){try{final JSONObject data=BackupEngine.read(BackupActivity.this,file);final ArrayList<String> info=new ArrayList<String>();info.add("Preferințe · "+BackupEngine.GROUPS.length+" grupuri");info.add("Notițe · "+(data.isNull("notes")?0:data.getJSONArray("notes").length()));info.add("Fundal · "+(data.isNull("wallpaper")?"Nu":"Da"));String words=data.getJSONObject("dictionary").getString("words");info.add("Dicționar · "+(words.isEmpty()?0:words.split("\n").length)+" cuvinte");info.add("Copia curentă se salvează automat");ui(new Runnable(){public void run(){busy=false;list("Previzualizare backup",info,0,new Choice(){public void pick(int i){}},"Restaurează",new Runnable(){public void run(){options("Înlocuiești datele Leo incluse?",new String[]{"Păstrează datele actuale","Restaurează acest backup"},new Choice(){public void pick(int i){if(i==1)restore(data);}});}});back=new Runnable(){public void run(){home();}};}});}catch(final Exception e){ui(new Runnable(){public void run(){home();notice("Backup respins: "+e.getMessage());}});}}});}
 private void restore(final JSONObject data){busy=true;begin("Restaurez Leo");root.addView(text("Se creează copia de siguranță și se aplică datele…",18));footer("","","Așteaptă");worker.execute(new Runnable(){public void run(){try{BackupEngine.restore(BackupActivity.this,data);ui(new Runnable(){public void run(){notice("Restaurare terminată; copia anterioară este în Documente Leo");startActivity(new Intent(BackupActivity.this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();}});}catch(final Exception e){ui(new Runnable(){public void run(){home();notice("Restaurare oprită: "+e.getMessage());}});}}});}
 public void onBackPressed(){if(busy){notice("Operație în curs");return;}super.onBackPressed();}
 public boolean onKeyDown(int key,android.view.KeyEvent e){if(busy&&key==android.view.KeyEvent.KEYCODE_BACK){notice("Operație în curs");return true;}return super.onKeyDown(key,e);}
}
